{
  "name": "pairwise_cost_advantage_loss",
  "intuition": "This loss leverages the advantage signals to focus on pairs where one option is better (higher advantage) than the other, promoting preference for higher advantage choices. Using logsigmoid of advantage differences encourages the model to assign higher probabilities to better options, aligning with RL4CO objectives.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l) * weight)",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    pairwise_adv = ops.sub(advantage_w, advantage_l)\n    loss_components = ops.mul(ops.logsigmoid(pairwise_adv), weight)\n    loss = ops.neg(ops.mean(loss_components))\n    return loss"
}

{
  "name": "loss_weighted_rank_gap_tanh_advantage",
  "intuition": "Shift from margin-based pairwise loss to ranking-based loss using tanh-transformed advantage-weighted rank gap, encouraging the model to respect pairwise quality ranking degree with smooth and bounded penalties.",
  "pseudocode": "rank_gap = rank_gap(lpw, lpl)\nadv_w = advantage_w\nadv_l = advantage_l\nadv_diff = adv_w - adv_l\nscore = tanh(rank_gap * adv_diff)\nloss = mean(weight * (1 - score))",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_difference",
    "link_family": "tanh",
    "agg_family": "weighted_mean",
    "constraint_family": "none"
  },
  "operators_used": ["rank_gap", "tanh", "mean", "mul", "sub", "add"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    rg = ops.rank_gap(lpw, lpl)\n    adv_diff = ops.sub(adv_w, adv_l)\n    score = ops.tanh(ops.mul(rg, adv_diff))\n    loss = ops.mean(ops.mul(weight, ops.sub(ops.ones_like(score), score)))\n    return loss"
}

{
  "name": "peer_loss_combined_010",
  "intuition": "This crossover combines the stable, well-understood pairwise logsigmoid loss with parameters from both parents, emphasizing the thresholding behavior of clamp stabilizing the loss argument. The combined approach leverages the weight of both parents' signals to refine the loss calculation without introducing instability, ensuring the loss remains numerically stable and semantically meaningful. The synergy of both hyperparameters and their respective formulations enhances robustness and consistent training signal.",
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale_region1 = float(extra.get('hyperparams', {}).get('scale', 1.9496803035382082))\n    scale_region2 = float(extra.get('hyperparams', {}).get('scale', 0.6752757766189963))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n    # Combine the scaling from parent 0 with parent 1's scale\n    scaled_diff_1 = alpha * scale_region1 * (lpw - lpl) - 0.1 * gap\n    scaled_diff_2 = alpha * scale_region2 * (lpw - lpl)\n    # Choose an intermediate value to stabilize\n    x = ops.maximum(scaled_diff_1, scaled_diff_2)\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()",
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b", "delta_z", "delta_rank", "delta_regret", "advantage_w", "advantage_l", "advantage_gap"]
  },
