{
  "name": "peer_loss_combined_010_stabilized",
  "intuition": "Removed redundant scale parameters and simplified the scaled difference to a single stable linear scaling of the log probability difference adjusted by the detached cost gap. Clamped the input to logsigmoid to [-20, 20] for numerical stability. Removed complex maximum between two scaled diffs to reduce instability and potential oscillations. Kept weighting multiplicative and mean aggregation to preserve general loss semantics with improved stability and simplicity.",
  "pseudocode": "lpw = batch['log_prob_w']\nlpl = batch['log_prob_l']\ngap = (batch['cost_b'] - batch['cost_a']).detach()\nx = alpha * (lpw - lpl) - 0.1 * gap\nx = clamp(x, -20, 20)\nloss = -logsigmoid(x)\nif weight is not None: loss = loss * weight\nreturn mean(loss)",
  "hyperparams": {
    "alpha": 1.0,
    "clamp_min": -20.0,
    "clamp_max": 20.0,
    "gap_scale": 0.1
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    gap_scale = float(extra.get('hyperparams', {}).get('gap_scale', 0.1))\n    clamp_min = float(extra.get('hyperparams', {}).get('clamp_min', -20.0))\n    clamp_max = float(extra.get('hyperparams', {}).get('clamp_max', 20.0))\n    gap = (batch['cost_b'] - batch['cost_a']).detach()\n    x = ops.sub(ops.mul(alpha, ops.sub(lpw, lpl)), ops.mul(gap_scale, gap))\n    x = ops.clamp(x, clamp_min, clamp_max)\n    loss = ops.neg(ops.logsigmoid(x))\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return ops.mean(loss)",
  "theoretical_basis": "",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "cost_a",
      "cost_b"
    ]
  }
}

{
  "name": "pairwise_advantage_difference",
  "intuition": "This loss measures the pairwise difference in advantages, encouraging the model to prefer higher advantage samples. By comparing advantage_w and advantage_l, it promotes policies that rank better actions with higher advantage values, aligning with RL objectives. The cost_gap signal ensures focus on relative differences rather than absolute scores, reducing bias from scaling issues.",
  "pseudocode": "loss = -mean(logsigmoid((advantage_w - advantage_l) * weight))",
  "hyperparams": {
    "paradigm_family": "pairwise_comparison",
    "signal_family": "advantage_signal",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "relative_difference",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    weight = batch['weight']\n    # Compute pairwise advantage difference\n    diff = ops.sub(advantage_w, advantage_l)\n    # Apply sigmoid to the scaled difference\n    loss_mean = ops.mean(ops.logsigmoid(ops.mul(diff, weight)))\n    # Negative because lower advantage difference preferred in lower_is_better setting\n    return ops.neg(loss_mean)"
}

{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss encourages the model to assign higher probability to pairs with better advantages and smaller cost gaps, directly aligning with preference for improved candidate pairs. By combining advantage signals with cost gaps, it emphasizes better-ranked and lower-cost options, reinforcing beneficial selections in RL4CO training.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l) + logsigmoid(-cost_gap))",
  "hyperparams": {
    "paradigm_family": "pairwise_comparison",
    "signal_family": "advantage_cost",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "duality"
  },
  "operators_used": ["logsigmoid", "add", "sub", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    advantage_w = batch.get('advantage_w', ops.zeros_like(log_prob_w))\n    advantage_l = batch.get('advantage_l', ops.zeros_like(log_prob_l))\n    cost_gap = batch['cost_gap']\n    weight = batch['weight']\n    advantage_diff = ops.sub(advantage_w, advantage_l)\n    cost_diff = ops.neg(cost_gap)\n    pairwise_adv = ops.logsigmoid(advantage_diff)\n    pairwise_cost = ops.logsigmoid(cost_diff)\n    loss_components = [pairwise_adv, pairwise_cost]\n    combined_loss = ops.mean(ops.stack(loss_components))\n    return ops.neg(combined_loss)"
}
